(() => {
 const M=CVA,m=x=>'£'+Number(x).toFixed(3)+'m',pct=x=>(x*100).toFixed(2)+'%',n=x=>Number(x).toFixed(4),green='#285e46',amber='#c9984d';
 const slider=(id,label,min,max,step,value,unit='£m')=>({id,label,min,max,step,value,unit}),select=(id,label,options,value)=>({id,label,options,value});
 const bars=(labels,values)=>labels.map((label,i)=>({label,value:values[i],color:['#285e46','#9fc774','#c9984d','#7b999e'][i%4]}));
 window.CVA_UI={m,pct,n,slider,select,bars,green,amber};
 window.CVA_LESSONS=[{id:'cva-value',name:'What is CVA?',stage:'01 · Exposure and valuation',title:'What is a counterparty promise worth?',intro:'Credit valuation adjustment (CVA) reduces a default-free value to reflect potential loss if the counterparty fails. CVA risk capital concerns changes in that adjustment.',chart:'Where the expected loss comes from',inputs:[slider('exposure','Exposure at final time point',0,100,1,20),slider('spread','Flat counterparty spread',0,1000,10,150,'bps'),slider('lgd','Market-consensus LGD',20,80,5,60,'%'),slider('years','Exposure horizon',1,10,.5,5,'years'),slider('rate','Risk-free discount rate',0,10,.25,3,'%')],challenge:'Double the exposure, then double the spread. Do the two changes have exactly the same effect?',formula:'CVA ≈ Σt Discount(t) × EPE(t) × LGD × [Survival(t−1) − Survival(t)]',key:'Teaching discretisation under independence. Flat hazard approximation λ ≈ spread / LGD; survival = exp(−λt). CVA is expressed as a positive loss.',simpleTitle:'An expected loss today can change before anyone defaults',simple:'You may be owed more in a future market state than you are owed today. CVA combines those future positive exposures with market-implied default probabilities and loss severity. Its value can rise as the counterparty’s spread widens or as potential exposure grows.',scope:'Twenty time intervals, synthetic EPE(t) = final exposure × √(t / horizon), constant LGD and rate, no wrong-way risk. The spread-to-hazard relationship is an approximation, not a CDS-curve bootstrap. This is a CVA value illustration, not the SA-CVA capital formula.',pages:[[404,'5.5–5.6 · regulatory CVA'],[405,'5.7–5.9 · inputs'],[406,'5.10–5.12 · exposure models']],notes:[['CVA, CVA risk and counterparty default risk','CVA is a valuation adjustment. CVA risk is the risk that this value changes when spreads or exposure drivers move. Counterparty credit risk capital addresses default exposure separately. Do not add a CVA value mechanically to the SA-CVA sensitivity capital total.'],['Unilateral regulatory CVA','The PRA calculation assumes the firm itself is free from default risk. An own-credit benefit (DVA) is therefore not used to reduce this regulatory CVA.']],compute(s){const r=M.value(s);return {stats:[['Illustrative CVA',m(r.value)],['Cumulative market PD',pct(r.pd)],['Flat hazard',pct(r.lambda)]],series:[{name:'Cumulative CVA (£m)',color:green,data:r.rows.map((row,i)=>[row.t,M.sum(r.rows.slice(0,i+1).map(x=>x.loss))])}],xlabel:'Years into the exposure horizon',headers:['Time (years)','Expected positive exposure','Interval default probability','Discount factor','CVA contribution'],rows:r.rows.map(x=>[x.t.toFixed(2),m(x.epe),pct(x.dp),n(x.discount),m(x.loss)]),explanation:`The illustrative expected discounted loss is ${m(r.value)}. Exposure is scaled by loss severity and each interval’s default probability. A higher CVA is a valuation loss even if the counterparty has not defaulted.`,note:'The chart accumulates expected loss across time. SA-CVA capital, developed later, measures sensitivity to changes in the inputs.'};}}];
})();
